/* v9.11.44 | 50 source-indexed, instructor-level questions for PCT II Final Review Sheet. Every study question 1–50 represented once. Technical answer rules drawn from established clinical teaching; instructor sheet itself lists prompts, not answer keys. Avoid interpreting these as verified verbatim slide questions or a replacement for current PCS. */
(()=>{'use strict';window.MD_PCT2_FINAL_REVIEW_1144=[{"id":"PCT2-FINAL-REVIEW-1144-01","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":1,"topic":"Final Review Point 1","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 1","source":"Uploaded PCT II Final Review Sheet, Study Question 1","prompt":"A farmworker develops pinpoint pupils, bronchorrhea, sweating, muscle fasciculations and bradycardia after handling insecticide. Which toxidrome best explains the findings?","choices":["Anticholinergic toxicity from reduced acetylcholine signalling","Cholinergic excess from organophosphate-related acetylcholinesterase inhibition","Sympathomimetic toxicity from adrenergic stimulation","Opioid toxicity from opioid-receptor activation"],"answer":"B","whyCorrect":"Organophosphates inhibit acetylcholinesterase, producing excess acetylcholine at muscarinic and nicotinic sites.","explanation":"Organophosphates inhibit acetylcholinesterase, producing excess acetylcholine at muscarinic and nicotinic sites.","whyWrong":{"Anticholinergic toxicity from reduced acetylcholine signalling":"Anticholinergics typically cause dry skin and mucosa rather than marked secretions.","Sympathomimetic toxicity from adrenergic stimulation":"Sympathomimetics typically cause tachycardia, agitation and sweating rather than a prominent wet cholinergic pattern.","Opioid toxicity from opioid-receptor activation":"Opioids can cause miosis and depressed respiration but not typical cholinergic secretions and fasciculations."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-02","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":2,"topic":"Final Review Point 2","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 2","source":"Uploaded PCT II Final Review Sheet, Study Question 2","prompt":"Following a large hemorrhage, a patient's pulse oximeter reads 99% while their skin is cool and they are becoming confused. What is the main limitation of that reading?","choices":["It directly measures the absolute amount of circulating blood","It confirms that end-organ perfusion is adequate","It rules out significant anemia or blood loss","It reflects the saturation of remaining hemoglobin, not total oxygen delivery"],"answer":"D","whyCorrect":"SpO2 can remain normal after substantial hemorrhage despite reduced oxygen-carrying capacity and impaired tissue perfusion.","explanation":"SpO2 can remain normal after substantial hemorrhage despite reduced oxygen-carrying capacity and impaired tissue perfusion.","whyWrong":{"It directly measures the absolute amount of circulating blood":"Pulse oximetry does not quantify circulating blood volume.","It confirms that end-organ perfusion is adequate":"A normal saturation does not establish perfusion or adequate oxygen delivery.","It rules out significant anemia or blood loss":"Significant blood loss or anemia can coexist with a high saturation."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-03","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":3,"topic":"Final Review Point 3","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 3","source":"Uploaded PCT II Final Review Sheet, Study Question 3","prompt":"A worker collapses during extreme heat exposure, is confused and has a high core temperature. Which distinction is most concerning?","choices":["Altered CNS function indicates suspected heat stroke rather than uncomplicated heat exhaustion","Profuse sweating excludes heat stroke","Muscle cramps alone confirm heat stroke","A normal pulse would exclude dangerous heat illness"],"answer":"A","whyCorrect":"Central nervous system dysfunction with marked hyperthermia is a defining warning feature of heat stroke.","explanation":"Central nervous system dysfunction with marked hyperthermia is a defining warning feature of heat stroke.","whyWrong":{"Profuse sweating excludes heat stroke":"Sweating may still be present in exertional heat stroke.","Muscle cramps alone confirm heat stroke":"Cramps can occur in milder heat illness without heat stroke.","A normal pulse would exclude dangerous heat illness":"Vital signs can vary; a single pulse value cannot rule it out."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-04","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":4,"topic":"Final Review Point 4","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 4","source":"Uploaded PCT II Final Review Sheet, Study Question 4","prompt":"A patient reports sudden, excruciating unilateral pain around one eye with tearing and nasal congestion, recurring at similar times for weeks. Which headache type fits best?","choices":["Tension-type headache","Cluster headache","Migraine without autonomic features","Sinus headache associated with infection"],"answer":"B","whyCorrect":"Cluster headaches cause severe unilateral orbital pain with ipsilateral autonomic findings.","explanation":"Cluster headaches cause severe unilateral orbital pain with ipsilateral autonomic findings.","whyWrong":{"Tension-type headache":"Tension headache more often causes bilateral pressure without striking autonomic signs.","Migraine without autonomic features":"Migraine may be unilateral but the short repeated attacks and autonomic pattern are especially characteristic of cluster.","Sinus headache associated with infection":"Sinusitis usually has additional infectious and nasal symptoms rather than stereotyped attacks."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-05","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":5,"topic":"Final Review Point 5","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 5","source":"Uploaded PCT II Final Review Sheet, Study Question 5","prompt":"Which pattern of daily habits most increases a person's risk for chronic GI complaints and disease?","choices":["Heavy alcohol intake, smoking, low-fiber diet and frequent NSAID use","Balanced meals, adequate hydration and regular activity","Moderate fiber intake with avoidance of tobacco","Maintaining hygiene and limiting alcohol"],"answer":"A","whyCorrect":"Alcohol, tobacco, low fiber intake and NSAID exposure contribute to various GI disorders.","explanation":"Alcohol, tobacco, low fiber intake and NSAID exposure contribute to various GI disorders.","whyWrong":{"Balanced meals, adequate hydration and regular activity":"These habits generally reduce common GI risks.","Moderate fiber intake with avoidance of tobacco":"This combination avoids two common contributors.","Maintaining hygiene and limiting alcohol":"Hygiene and limited alcohol are protective rather than major risk factors."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-06","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":6,"topic":"Final Review Point 6","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 6","source":"Uploaded PCT II Final Review Sheet, Study Question 6","prompt":"After a patient awakens to find a bat in their bedroom, there is no visible bite mark. Which concern should guide the assessment?","choices":["Rabies exposure is excluded if skin looks normal","Possible rabies exposure can require urgent public-health evaluation even without an obvious bite","Immediate tourniquet application prevents bat-borne rabies","Rabies exposure is relevant only if the bat is visibly ill"],"answer":"B","whyCorrect":"Small bat bites can be difficult to recognize; possible exposure requires prompt risk assessment and public health guidance.","explanation":"Small bat bites can be difficult to recognize; possible exposure requires prompt risk assessment and public health guidance.","whyWrong":{"Rabies exposure is excluded if skin looks normal":"The absence of a visible puncture cannot always exclude a bat exposure.","Immediate tourniquet application prevents bat-borne rabies":"A tourniquet neither prevents rabies nor serves routine bite care.","Rabies exposure is relevant only if the bat is visibly ill":"Appearance cannot reliably establish whether the animal carries rabies."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-07","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":7,"topic":"Final Review Point 7","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 7","source":"Uploaded PCT II Final Review Sheet, Study Question 7","prompt":"A conscious patient has worsening neuroglycopenic symptoms after prolonged fasting. Why is circulating glucose particularly important for normal brain activity?","choices":["The brain stores large glucose reserves for multiple days","Neurons directly convert hemoglobin to glucose","The brain never uses alternative fuels under any circumstance","The brain has limited glycogen reserves and ordinarily needs a continuous glucose supply"],"answer":"D","whyCorrect":"Neurons ordinarily depend heavily on circulating glucose because local energy reserves are limited.","explanation":"Neurons ordinarily depend heavily on circulating glucose because local energy reserves are limited.","whyWrong":{"The brain stores large glucose reserves for multiple days":"Brain glycogen stores are limited.","Neurons directly convert hemoglobin to glucose":"Hemoglobin transports gases; it is not converted into glucose by neurons.","The brain never uses alternative fuels under any circumstance":"Ketones can support brain metabolism during prolonged fasting, although glucose remains important."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-08","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":8,"topic":"Final Review Point 8","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 8","source":"Uploaded PCT II Final Review Sheet, Study Question 8","prompt":"A patient with known primary adrenal insufficiency becomes hypotensive, weak and nauseated during a febrile illness. Which process most likely explains their deterioration?","choices":["An increased stress requirement for cortisol that the adrenal glands cannot meet","Excess endogenous cortisol causing hyperglycemia and hypertension","Abrupt increase in thyroid hormone production","An isolated rise in insulin without other hormonal disturbance"],"answer":"A","whyCorrect":"An Addisonian crisis can arise when illness increases cortisol needs beyond deficient adrenal production.","explanation":"An Addisonian crisis can arise when illness increases cortisol needs beyond deficient adrenal production.","whyWrong":{"Excess endogenous cortisol causing hyperglycemia and hypertension":"Cortisol excess produces a contrasting endocrine state.","Abrupt increase in thyroid hormone production":"Thyroid excess does not explain the adrenal-crisis mechanism.","An isolated rise in insulin without other hormonal disturbance":"An isolated insulin rise is not the underlying adrenal deficit."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-09","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":9,"topic":"Final Review Point 9","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 9","source":"Uploaded PCT II Final Review Sheet, Study Question 9","prompt":"After removing gloves following a patient contact, which routine action most directly prevents the spread of infectious organisms?","choices":["Use a fresh pair of gloves without hand hygiene","Replace hand hygiene with a mask in every encounter","Perform hand hygiene before the next patient or equipment contact","Wait for symptoms before taking infection-control precautions"],"answer":"C","whyCorrect":"Hand hygiene is central to breaking transmission between contacts.","explanation":"Hand hygiene is central to breaking transmission between contacts.","whyWrong":{"Use a fresh pair of gloves without hand hygiene":"Gloves are not a substitute for hand hygiene.","Replace hand hygiene with a mask in every encounter":"A mask addresses certain exposures but does not replace clean hands.","Wait for symptoms before taking infection-control precautions":"Transmission can occur without obvious symptoms."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-10","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":10,"topic":"Final Review Point 10","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 10","source":"Uploaded PCT II Final Review Sheet, Study Question 10","prompt":"A sexually active patient asks what lowers the chance of transmitting many STIs during intercourse. Which recommendation is most appropriate?","choices":["Antibiotics before every encounter regardless of infection","Avoiding contact only when visible genital lesions are present","Using oral contraceptives as the principal infection barrier","Consistent correct barrier protection together with testing and appropriate treatment"],"answer":"D","whyCorrect":"Condoms and other barriers reduce transmission risk, while testing and treatment address infections that may be asymptomatic.","explanation":"Condoms and other barriers reduce transmission risk, while testing and treatment address infections that may be asymptomatic.","whyWrong":{"Antibiotics before every encounter regardless of infection":"Prophylactic antibiotics are not an appropriate universal prevention strategy.","Avoiding contact only when visible genital lesions are present":"Many STIs are transmitted without visible lesions.","Using oral contraceptives as the principal infection barrier":"Hormonal contraception prevents pregnancy, not STI transmission."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-11","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":11,"topic":"Final Review Point 11","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 11","source":"Uploaded PCT II Final Review Sheet, Study Question 11","prompt":"A newly diagnosed adult with diabetes still produces insulin but tissues respond poorly to it. Which comparison is correct?","choices":["Type 1 diabetes is caused mainly by insulin resistance alone","Type 2 diabetes commonly features insulin resistance; type 1 usually involves autoimmune beta-cell destruction","Type 2 diabetes always features complete absence of endogenous insulin at diagnosis","Both types always require the same insulin output and mechanism"],"answer":"B","whyCorrect":"Type 2 typically involves resistance and progressive beta-cell dysfunction; type 1 typically reflects autoimmune insulin deficiency.","explanation":"Type 2 typically involves resistance and progressive beta-cell dysfunction; type 1 typically reflects autoimmune insulin deficiency.","whyWrong":{"Type 1 diabetes is caused mainly by insulin resistance alone":"Type 1 is primarily characterized by beta-cell destruction.","Type 2 diabetes always features complete absence of endogenous insulin at diagnosis":"Many with type 2 retain endogenous insulin initially.","Both types always require the same insulin output and mechanism":"The mechanisms and degree of insulin deficiency differ."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-12","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":12,"topic":"Final Review Point 12","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 12","source":"Uploaded PCT II Final Review Sheet, Study Question 12","prompt":"A patient with suspected brain herniation develops hypertension, bradycardia and irregular breathing. What does this combination suggest?","choices":["A compensated mild concussion without raised pressure","Cushing reflex associated with critically increased intracranial pressure","A classic isolated spinal shock pattern","A benign normal response to sleep"],"answer":"B","whyCorrect":"The combination is Cushing's triad, a late warning of increased ICP and impending herniation.","explanation":"The combination is Cushing's triad, a late warning of increased ICP and impending herniation.","whyWrong":{"A compensated mild concussion without raised pressure":"Simple concussion does not normally produce this late pressure response.","A classic isolated spinal shock pattern":"Spinal shock produces loss of spinal reflexes and often low blood pressure.","A benign normal response to sleep":"This is not a routine sleep-related pattern in an ill patient."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-13","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":13,"topic":"Final Review Point 13","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 13","source":"Uploaded PCT II Final Review Sheet, Study Question 13","prompt":"During healing of a significant burn, what process produces new vascularized granulation tissue before later maturation and remodeling?","choices":["The proliferative phase of wound healing","The initial hemostatic phase alone","The late remodeling phase before granulation develops","An unrelated primary immune rejection event"],"answer":"A","whyCorrect":"Granulation and re-epithelialization are hallmarks of the proliferative phase.","explanation":"Granulation and re-epithelialization are hallmarks of the proliferative phase.","whyWrong":{"The initial hemostatic phase alone":"Hemostasis focuses on initial clot formation.","The late remodeling phase before granulation develops":"Remodeling modifies existing repair tissue later.","An unrelated primary immune rejection event":"Immune rejection does not describe normal healing phases."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-14","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":14,"topic":"Final Review Point 14","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 14","source":"Uploaded PCT II Final Review Sheet, Study Question 14","prompt":"A patient has weight loss despite appetite, tremor, heat intolerance, tachycardia and prominent eyes. Which disorder is especially suggested?","choices":["Hashimoto hypothyroidism","Primary adrenal insufficiency","Graves disease causing hyperthyroidism","Myxedema coma"],"answer":"C","whyCorrect":"Graves disease can cause thyroid hormone excess with thyroid-associated eye findings.","explanation":"Graves disease can cause thyroid hormone excess with thyroid-associated eye findings.","whyWrong":{"Hashimoto hypothyroidism":"Hypothyroidism more often causes cold intolerance and slowing.","Primary adrenal insufficiency":"Adrenal insufficiency does not explain exophthalmos plus thyrotoxicosis.","Myxedema coma":"Myxedema coma is severe thyroid deficiency, not hormone excess."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-15","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":15,"topic":"Final Review Point 15","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 15","source":"Uploaded PCT II Final Review Sheet, Study Question 15","prompt":"A patient with known diabetes is confused, has documented low blood glucose and is too drowsy to swallow safely. What is the key oral-treatment decision?","choices":["Force sweetened fluid into the patient's mouth","Give oral glucose as soon as they have a palpable pulse","Delay repeat assessment until the patient is fully alert","Withhold oral glucose to avoid aspiration and use the applicable hypoglycemia directive"],"answer":"D","whyCorrect":"Unsafe swallowing makes oral glucose hazardous; management depends on the authorized hypoglycemia protocol and ongoing assessment.","explanation":"Unsafe swallowing makes oral glucose hazardous; management depends on the authorized hypoglycemia protocol and ongoing assessment.","whyWrong":{"Force sweetened fluid into the patient's mouth":"Forcing fluid risks aspiration.","Give oral glucose as soon as they have a palpable pulse":"Pulse presence does not establish safe swallowing.","Delay repeat assessment until the patient is fully alert":"Repeated glucose and patient reassessment matter during treatment."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-16","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":16,"topic":"Final Review Point 16","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 16","source":"Uploaded PCT II Final Review Sheet, Study Question 16","prompt":"Which burn complication is most immediately life threatening following smoke inhalation and facial thermal injury?","choices":["Late hypertrophic scar formation","Post-healing contracture development","Progressive airway edema and respiratory compromise","Long-term pigment change alone"],"answer":"C","whyCorrect":"Thermal or inhalational airway injury can lead to rapidly evolving obstruction.","explanation":"Thermal or inhalational airway injury can lead to rapidly evolving obstruction.","whyWrong":{"Late hypertrophic scar formation":"Scars form during later healing.","Post-healing contracture development":"Contractures are generally delayed complications.","Long-term pigment change alone":"Pigment change is not the immediate threat."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-17","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":17,"topic":"Final Review Point 17","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 17","source":"Uploaded PCT II Final Review Sheet, Study Question 17","prompt":"An unwell patient is sweaty, pale, trembling and confused after taking insulin without eating. Which process best explains the presentation?","choices":["Hyperglycemia causing osmotic diuresis as the sole process","Slow development of thyroid deficiency","Isolated elevated serum sodium with no glucose change","Acute hypoglycemia with autonomic and neuroglycopenic effects"],"answer":"D","whyCorrect":"Adrenergic symptoms and confusion together are highly consistent with symptomatic hypoglycemia.","explanation":"Adrenergic symptoms and confusion together are highly consistent with symptomatic hypoglycemia.","whyWrong":{"Hyperglycemia causing osmotic diuresis as the sole process":"Hyperglycemia more often produces thirst, urination and dehydration over time.","Slow development of thyroid deficiency":"Hypothyroidism is not this rapid presentation.","Isolated elevated serum sodium with no glucose change":"Sodium excess does not specifically explain the insulin-associated pattern."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-18","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":18,"topic":"Final Review Point 18","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 18","source":"Uploaded PCT II Final Review Sheet, Study Question 18","prompt":"Which finding is one of the core components of the Los Angeles Prehospital Stroke Screen?","choices":["Bilateral equal facial and arm movement required to indicate stroke","Sudden isolated abdominal pain as a motor screening component","Elevated temperature alone as confirmation of a stroke bypass","Unilateral arm drift or grip asymmetry on motor examination"],"answer":"D","whyCorrect":"LAPSS assesses unilateral motor asymmetry, alongside historical and blood glucose criteria.","explanation":"LAPSS assesses unilateral motor asymmetry, alongside historical and blood glucose criteria.","whyWrong":{"Bilateral equal facial and arm movement required to indicate stroke":"Equal bilateral function is not the focal deficit sought.","Sudden isolated abdominal pain as a motor screening component":"Abdominal pain is not part of its focal motor assessment.","Elevated temperature alone as confirmation of a stroke bypass":"Temperature does not independently establish stroke-screen eligibility."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-19","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":19,"topic":"Final Review Point 19","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 19","source":"Uploaded PCT II Final Review Sheet, Study Question 19","prompt":"A previously well adult develops nausea, vomiting, diarrhea and cramping after several family members have the same illness. What is the most likely broad syndrome?","choices":["Mechanical bowel obstruction from a fixed lesion","Acute gastroenteritis affecting the stomach and intestines","Portal hypertension with esophageal varices","Acute pancreatitis from ductal inflammation"],"answer":"B","whyCorrect":"Acute gastroenteritis is often infectious and produces vomiting, diarrhea and cramping.","explanation":"Acute gastroenteritis is often infectious and produces vomiting, diarrhea and cramping.","whyWrong":{"Mechanical bowel obstruction from a fixed lesion":"Obstruction more often features distension and impaired passage of stool/gas.","Portal hypertension with esophageal varices":"Varices typically cause upper GI hemorrhage rather than contagious diarrhea.","Acute pancreatitis from ductal inflammation":"Pancreatitis commonly causes severe upper abdominal pain and different findings."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-20","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":20,"topic":"Final Review Point 20","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 20","source":"Uploaded PCT II Final Review Sheet, Study Question 20","prompt":"During ventilation of a patient with elevated intracranial pressure, why can excessive hyperventilation worsen brain injury?","choices":["Hypocapnia causes cerebral vasoconstriction and may reduce cerebral blood flow","It always lowers ICP without any cerebral perfusion tradeoff","It raises arterial CO2 and causes global vasodilation","It permanently eliminates the risk of herniation"],"answer":"A","whyCorrect":"Lowering PaCO2 excessively constricts cerebral vessels, potentially causing ischemia.","explanation":"Lowering PaCO2 excessively constricts cerebral vessels, potentially causing ischemia.","whyWrong":{"It always lowers ICP without any cerebral perfusion tradeoff":"Transient ICP effects do not justify unrestrained ventilation.","It raises arterial CO2 and causes global vasodilation":"Hyperventilation lowers, rather than raises, CO2.","It permanently eliminates the risk of herniation":"It cannot eliminate a structural intracranial emergency."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-21","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":21,"topic":"Final Review Point 21","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 21","source":"Uploaded PCT II Final Review Sheet, Study Question 21","prompt":"A diabetic patient has deep, rapid respirations without primary lung pathology and a metabolic acidosis. What is the physiological role of this pattern?","choices":["CO2 retention to make blood more acidic","A primary mechanism to increase bicarbonate production in the lungs","A sign that acid-base status must be normal","Respiratory compensation by blowing off CO2, as in diabetic ketoacidosis"],"answer":"D","whyCorrect":"Kussmaul respirations compensate for metabolic acidosis by reducing CO2.","explanation":"Kussmaul respirations compensate for metabolic acidosis by reducing CO2.","whyWrong":{"CO2 retention to make blood more acidic":"CO2 retention increases acidity rather than corrects it.","A primary mechanism to increase bicarbonate production in the lungs":"The lungs regulate CO2, not generate bicarbonate.","A sign that acid-base status must be normal":"The pattern may signal major metabolic disturbance."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-22","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":22,"topic":"Final Review Point 22","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 22","source":"Uploaded PCT II Final Review Sheet, Study Question 22","prompt":"Following major hemorrhage, which change can mark transition from compensated to decompensated hypovolemic shock?","choices":["Stable consciousness and preserved perfusion as blood volume keeps falling","Isolated mild tachycardia with normal blood pressure as proof of decompensation","Falling blood pressure with deteriorating mental status despite earlier tachycardia","A single normal oxygen saturation showing recovered circulation"],"answer":"C","whyCorrect":"Compensation may maintain BP initially; hypotension and altered mental status suggest deteriorating perfusion.","explanation":"Compensation may maintain BP initially; hypotension and altered mental status suggest deteriorating perfusion.","whyWrong":{"Stable consciousness and preserved perfusion as blood volume keeps falling":"These signs are not evidence of decompensation.","Isolated mild tachycardia with normal blood pressure as proof of decompensation":"Tachycardia alone can occur while compensation persists.","A single normal oxygen saturation showing recovered circulation":"SpO2 does not establish tissue perfusion."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-23","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":23,"topic":"Final Review Point 23","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 23","source":"Uploaded PCT II Final Review Sheet, Study Question 23","prompt":"After a carbohydrate-containing meal, which hormone normally helps reduce elevated blood glucose by promoting cellular uptake and storage?","choices":["Glucagon released from pancreatic alpha cells","Cortisol from the adrenal cortex","Insulin released from pancreatic beta cells","Epinephrine from the adrenal medulla"],"answer":"C","whyCorrect":"Insulin promotes cellular glucose uptake and storage, especially in muscle and adipose tissue.","explanation":"Insulin promotes cellular glucose uptake and storage, especially in muscle and adipose tissue.","whyWrong":{"Glucagon released from pancreatic alpha cells":"Glucagon generally increases circulating glucose.","Cortisol from the adrenal cortex":"Cortisol generally supports glucose availability.","Epinephrine from the adrenal medulla":"Epinephrine can increase blood glucose under stress."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-24","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":24,"topic":"Final Review Point 24","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 24","source":"Uploaded PCT II Final Review Sheet, Study Question 24","prompt":"An elderly patient with significant heart failure is given an excessive fluid bolus. Which complication is particularly important to monitor for?","choices":["Pulmonary edema from inadequate cardiac tolerance of the added volume","Guaranteed correction of all causes of hypotension","Sudden cure of chronic kidney disease","An inability to develop respiratory signs from overload"],"answer":"A","whyCorrect":"Reduced cardiac reserve can cause fluid overload and pulmonary edema.","explanation":"Reduced cardiac reserve can cause fluid overload and pulmonary edema.","whyWrong":{"Guaranteed correction of all causes of hypotension":"Fluid does not correct all hypotension mechanisms.","Sudden cure of chronic kidney disease":"Fluid administration cannot cure renal disease.","An inability to develop respiratory signs from overload":"Overload frequently creates respiratory distress."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-25","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":25,"topic":"Final Review Point 25","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 25","source":"Uploaded PCT II Final Review Sheet, Study Question 25","prompt":"Immediately after severe spinal cord trauma, a patient is flaccid below the injury and reflexes are absent. Which term describes this transient loss of spinal reflex activity?","choices":["Neurogenic shock","Cushing reflex","Spinal shock","Autonomic dysreflexia"],"answer":"C","whyCorrect":"Spinal shock denotes temporary loss of motor, sensory and reflex function below injury.","explanation":"Spinal shock denotes temporary loss of motor, sensory and reflex function below injury.","whyWrong":{"Neurogenic shock":"Neurogenic shock is primarily loss of sympathetic vascular tone causing hypotension, often with bradycardia.","Cushing reflex":"Cushing reflex reflects raised ICP.","Autonomic dysreflexia":"Autonomic dysreflexia is episodic sympathetic crisis in certain chronic spinal injuries."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-26","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":26,"topic":"Final Review Point 26","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 26","source":"Uploaded PCT II Final Review Sheet, Study Question 26","prompt":"A patient ingests a large amount of over-the-counter acetaminophen and is initially minimally symptomatic. What serious delayed complication is most important?","choices":["Immediate predictable profound miosis from opioid receptor stimulation","Hepatocellular injury and possible acute liver failure","Isolated cholinergic bronchorrhea from acetylcholinesterase inhibition","Universal severe bradycardia without organ injury"],"answer":"B","whyCorrect":"Acetaminophen toxicity may produce delayed hepatic injury despite mild early symptoms.","explanation":"Acetaminophen toxicity may produce delayed hepatic injury despite mild early symptoms.","whyWrong":{"Immediate predictable profound miosis from opioid receptor stimulation":"Acetaminophen is not an opioid.","Isolated cholinergic bronchorrhea from acetylcholinesterase inhibition":"Acetaminophen is not an organophosphate.","Universal severe bradycardia without organ injury":"Cardiac rate alone is not its defining delayed toxicity."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-27","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":27,"topic":"Final Review Point 27","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 27","source":"Uploaded PCT II Final Review Sheet, Study Question 27","prompt":"After repeated forceful retching, a patient develops bright red hematemesis. Which lesion is characteristic of Mallory–Weiss syndrome?","choices":["A ruptured full-thickness esophageal wall","A bleeding ulcer confined to the lower intestine","A mucosal tear near the gastroesophageal junction","A dilated portal-hypertension collateral as the only mechanism"],"answer":"C","whyCorrect":"Mallory–Weiss tears involve mucosa near the distal esophagus following vomiting or retching.","explanation":"Mallory–Weiss tears involve mucosa near the distal esophagus following vomiting or retching.","whyWrong":{"A ruptured full-thickness esophageal wall":"Full-thickness rupture is Boerhaave syndrome.","A bleeding ulcer confined to the lower intestine":"A lower intestinal ulcer does not explain the typical tear.","A dilated portal-hypertension collateral as the only mechanism":"Variceal hemorrhage has a different portal-hypertensive mechanism."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-28","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":28,"topic":"Final Review Point 28","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 28","source":"Uploaded PCT II Final Review Sheet, Study Question 28","prompt":"A patient in profound hypothermic cardiac arrest is being resuscitated. What is an essential overarching management principle?","choices":["Declare irreversible death solely because the pulse is difficult to detect","Prevent further heat loss, perform appropriate resuscitation and actively coordinate rewarming while following the hypothermia arrest protocol","Use the standard normothermic medication and shock sequence without considering temperature","Delay all CPR until normal body temperature has been restored"],"answer":"B","whyCorrect":"Profound hypothermia alters arrest assessment and resuscitation priorities; rewarming is central alongside indicated resuscitation.","explanation":"Profound hypothermia alters arrest assessment and resuscitation priorities; rewarming is central alongside indicated resuscitation.","whyWrong":{"Declare irreversible death solely because the pulse is difficult to detect":"Profound hypothermia can make circulation hard to detect.","Use the standard normothermic medication and shock sequence without considering temperature":"Hypothermia protocols can modify medication and defibrillation timing.","Delay all CPR until normal body temperature has been restored":"Delaying indicated CPR until warm would be unsafe."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-29","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":29,"topic":"Final Review Point 29","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 29","source":"Uploaded PCT II Final Review Sheet, Study Question 29","prompt":"After blunt head injury, a patient briefly loses consciousness, awakens and later rapidly deteriorates with unilateral pupillary changes. What is the classic bleeding pattern of concern?","choices":["Uncomplicated mild headache from tension alone","A stable isolated peripheral nerve injury","Epidural hematoma with a possible lucid interval","Chronic nontraumatic migraine without neurological decline"],"answer":"C","whyCorrect":"An epidural bleed may be followed by a lucid interval then worsening as hematoma expands.","explanation":"An epidural bleed may be followed by a lucid interval then worsening as hematoma expands.","whyWrong":{"Uncomplicated mild headache from tension alone":"The progressive neurological deterioration requires urgent evaluation.","A stable isolated peripheral nerve injury":"Peripheral nerve injury does not explain rising ICP signs.","Chronic nontraumatic migraine without neurological decline":"Migraine alone is not the typical consequence of this trauma sequence."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-30","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":30,"topic":"Final Review Point 30","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 30","source":"Uploaded PCT II Final Review Sheet, Study Question 30","prompt":"A patient has hypothermia, bradycardia, profound lethargy and very slow ventilation with known untreated hypothyroidism. Which endocrine emergency is suggested?","choices":["Thyroid storm from excessive thyroid hormone","Myxedema coma from severe thyroid hormone deficiency","Pheochromocytoma crisis with catecholamine excess","Classic Graves thyrotoxicosis"],"answer":"B","whyCorrect":"Myxedema coma is severe decompensated hypothyroidism with multisystem slowing and altered mental status.","explanation":"Myxedema coma is severe decompensated hypothyroidism with multisystem slowing and altered mental status.","whyWrong":{"Thyroid storm from excessive thyroid hormone":"Thyroid storm more often causes fever, agitation and tachycardia.","Pheochromocytoma crisis with catecholamine excess":"Catecholamine crisis generally produces sympathetic activation.","Classic Graves thyrotoxicosis":"Graves classically produces thyroid hormone excess."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-31","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":31,"topic":"Final Review Point 31","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 31","source":"Uploaded PCT II Final Review Sheet, Study Question 31","prompt":"During rescue, a profoundly hypothermic patient deteriorates when handled roughly and their cold limbs are aggressively moved. What is one important concern?","choices":["Rewarming of hands instantly restores central circulation","Afterdrop and cardiovascular instability during movement or rewarming","Rough handling reliably prevents ventricular dysrhythmias","Core temperature always rises immediately when peripheral limbs are heated"],"answer":"B","whyCorrect":"Afterdrop refers to continued core temperature decline during rescue/rewarming, and rough handling may provoke instability.","explanation":"Afterdrop refers to continued core temperature decline during rescue/rewarming, and rough handling may provoke instability.","whyWrong":{"Rewarming of hands instantly restores central circulation":"Local warming does not immediately correct core hypothermia.","Rough handling reliably prevents ventricular dysrhythmias":"Fragile hypothermic myocardium can be sensitive to rough handling.","Core temperature always rises immediately when peripheral limbs are heated":"Peripheral vasodilation can redistribute cold blood and worsen core temperature initially."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-32","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":32,"topic":"Final Review Point 32","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 32","source":"Uploaded PCT II Final Review Sheet, Study Question 32","prompt":"Following severe brain injury, the arms extend and internally rotate while the legs extend. Which interpretation is most appropriate?","choices":["Decorticate posturing with flexed arms toward the chest","A normal protective withdrawal response","Decerebrate posturing, generally associated with more caudal brain dysfunction","Voluntary stretching without neurological significance"],"answer":"C","whyCorrect":"Decerebrate posturing typically involves extensor responses and indicates serious neurological injury.","explanation":"Decerebrate posturing typically involves extensor responses and indicates serious neurological injury.","whyWrong":{"Decorticate posturing with flexed arms toward the chest":"Decorticate classically has flexed upper limbs.","A normal protective withdrawal response":"Pathological extension is not a normal pain withdrawal.","Voluntary stretching without neurological significance":"In this context the abnormal pattern suggests CNS damage."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-33","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":33,"topic":"Final Review Point 33","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 33","source":"Uploaded PCT II Final Review Sheet, Study Question 33","prompt":"A patient develops fever and headache following mosquito exposure during the summer; a severe case progresses to encephalitis. Which pathogen is an appropriate consideration?","choices":["West Nile virus","Rabies virus from animal saliva","Varicella-zoster virus from direct rash contact","Hepatitis B virus from blood exposure"],"answer":"A","whyCorrect":"West Nile virus is mosquito-borne and can cause neuroinvasive disease.","explanation":"West Nile virus is mosquito-borne and can cause neuroinvasive disease.","whyWrong":{"Rabies virus from animal saliva":"Rabies is usually linked to mammalian saliva exposures.","Varicella-zoster virus from direct rash contact":"Varicella transmission and typical presentation are different.","Hepatitis B virus from blood exposure":"Hepatitis B does not spread by mosquito vectors."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-34","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":34,"topic":"Final Review Point 34","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 34","source":"Uploaded PCT II Final Review Sheet, Study Question 34","prompt":"Following an abdominal injury, pain is vague, poorly localized and associated with distension. What type of structure is more likely responsible for the early discomfort?","choices":["Parietal peritoneum producing sharply localized pain","Superficial skeletal muscle producing cutaneous pain","A purely dermatomal sensory nerve problem","A hollow visceral organ producing visceral pain"],"answer":"D","whyCorrect":"Hollow viscera often produce diffuse visceral pain related to distension or spasm.","explanation":"Hollow viscera often produce diffuse visceral pain related to distension or spasm.","whyWrong":{"Parietal peritoneum producing sharply localized pain":"Parietal peritoneal pain is generally better localized.","Superficial skeletal muscle producing cutaneous pain":"Superficial injury has more focal somatic features.","A purely dermatomal sensory nerve problem":"Dermatomal neuropathy is a different mechanism."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-35","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":35,"topic":"Final Review Point 35","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 35","source":"Uploaded PCT II Final Review Sheet, Study Question 35","prompt":"A patient with worsening appendiceal inflammation develops sharply localized pain and guarding in the right lower quadrant. Which change explains the new quality of pain?","choices":["Continued isolated distension of the appendiceal lumen without peritoneal involvement","Increased gastric acid secretion","A migrating cerebral pain signal from the occipital cortex","Irritation of the parietal peritoneum causing somatic pain"],"answer":"D","whyCorrect":"Parietal peritoneal irritation produces better-localized somatic pain and guarding.","explanation":"Parietal peritoneal irritation produces better-localized somatic pain and guarding.","whyWrong":{"Continued isolated distension of the appendiceal lumen without peritoneal involvement":"Visceral distension alone usually causes poorly localized pain.","Increased gastric acid secretion":"Gastric acidity does not directly create localized peritoneal guarding.","A migrating cerebral pain signal from the occipital cortex":"The occipital cortex is not the source of the abdominal signs."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-36","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":36,"topic":"Final Review Point 36","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 36","source":"Uploaded PCT II Final Review Sheet, Study Question 36","prompt":"A diabetic patient improves after treatment of hypoglycemia and wants to decline transport. Which principle is essential before any nontransport decision?","choices":["Assume normal capacity from a single normal glucose reading","Leave immediately once the patient says they feel better","Rely on a family member's reassurance instead of reassessing the patient","Assess full recovery, decision-making capacity and applicable local treat-and-discharge requirements"],"answer":"D","whyCorrect":"Persistent risks, recurrent hypoglycemia and local protocol criteria require careful reassessment before disposition.","explanation":"Persistent risks, recurrent hypoglycemia and local protocol criteria require careful reassessment before disposition.","whyWrong":{"Assume normal capacity from a single normal glucose reading":"A single glucose value does not establish recovery or capacity.","Leave immediately once the patient says they feel better":"Subjective improvement does not replace objective reassessment.","Rely on a family member's reassurance instead of reassessing the patient":"Collateral reassurance cannot replace medical assessment."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-37","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":37,"topic":"Final Review Point 37","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 37","source":"Uploaded PCT II Final Review Sheet, Study Question 37","prompt":"A five-year-old develops hives, wheeze and hypotension minutes after an allergen exposure. Which initial medication has priority when anaphylaxis criteria are met?","choices":["Intramuscular epinephrine under the applicable PCP allergic-reaction directive","An oral antihistamine before treating airway and circulation compromise","A bronchodilator alone despite hypotension","Waiting for symptoms to resolve without immediate treatment"],"answer":"A","whyCorrect":"IM epinephrine is the first-line medication for anaphylaxis, with age/weight dosing governed by current directive.","explanation":"IM epinephrine is the first-line medication for anaphylaxis, with age/weight dosing governed by current directive.","whyWrong":{"An oral antihistamine before treating airway and circulation compromise":"Antihistamines do not treat life-threatening cardiovascular collapse.","A bronchodilator alone despite hypotension":"Bronchodilators do not replace epinephrine in systemic anaphylaxis.","Waiting for symptoms to resolve without immediate treatment":"Delaying epinephrine risks deterioration."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-38","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":38,"topic":"Final Review Point 38","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 38","source":"Uploaded PCT II Final Review Sheet, Study Question 38","prompt":"A child develops fever, cough, coryza and conjunctivitis, then a generalized rash after prodrome. Which vaccine-preventable infection is most characteristic?","choices":["Rubella with typically milder prodromal symptoms","Varicella with vesicles in multiple stages","Mumps with prominent parotid swelling","Measles (rubeola)"],"answer":"D","whyCorrect":"Measles commonly has the classic cough, coryza, conjunctivitis triad and subsequent rash.","explanation":"Measles commonly has the classic cough, coryza, conjunctivitis triad and subsequent rash.","whyWrong":{"Rubella with typically milder prodromal symptoms":"Rubella is often milder and may feature lymphadenopathy.","Varicella with vesicles in multiple stages":"Varicella produces crops of vesicles.","Mumps with prominent parotid swelling":"Mumps classically causes parotitis."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-39","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":39,"topic":"Final Review Point 39","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 39","source":"Uploaded PCT II Final Review Sheet, Study Question 39","prompt":"A climber develops severe headache, gait ataxia and confusion at high altitude. Which diagnosis should be considered urgently?","choices":["High-altitude cerebral edema","Uncomplicated acute mountain sickness without neurologic impairment","High-altitude pulmonary edema presenting only with cough and hypoxemia","Simple dehydration as the sole cause of focal neurological findings"],"answer":"A","whyCorrect":"Ataxia and altered mental status at altitude are serious warning signs of high-altitude cerebral edema.","explanation":"Ataxia and altered mental status at altitude are serious warning signs of high-altitude cerebral edema.","whyWrong":{"Uncomplicated acute mountain sickness without neurologic impairment":"Neurological deterioration suggests progression beyond uncomplicated AMS.","High-altitude pulmonary edema presenting only with cough and hypoxemia":"HAPE principally affects pulmonary gas exchange.","Simple dehydration as the sole cause of focal neurological findings":"Dehydration may coexist but should not explain away these high-risk signs."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-40","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":40,"topic":"Final Review Point 40","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 40","source":"Uploaded PCT II Final Review Sheet, Study Question 40","prompt":"A patient with known liver cirrhosis suddenly vomits a large volume of bright red blood and becomes hypotensive. What explains a major risk factor for this bleeding?","choices":["Portal hypertension causing dilated esophageal collateral veins","Increased systemic arterial pressure alone","Primary gallbladder contraction triggering upper GI rupture","Low gastric motility mechanically tearing the spleen"],"answer":"A","whyCorrect":"Cirrhosis can raise portal pressure and produce fragile esophageal varices prone to major hemorrhage.","explanation":"Cirrhosis can raise portal pressure and produce fragile esophageal varices prone to major hemorrhage.","whyWrong":{"Increased systemic arterial pressure alone":"Systemic BP is not the defining cause of portal varices.","Primary gallbladder contraction triggering upper GI rupture":"Gallbladder contraction is unrelated to variceal rupture.","Low gastric motility mechanically tearing the spleen":"A splenic tear is not the mechanism of esophageal bleeding."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-41","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":41,"topic":"Final Review Point 41","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 41","source":"Uploaded PCT II Final Review Sheet, Study Question 41","prompt":"A patient has central weight gain, rounded face, easy bruising, proximal weakness and hypertension. Which endocrine state best unifies these findings?","choices":["Chronic cortisol deficiency in Addison disease","Thyroid hormone deficiency alone","Chronic glucocorticoid excess in Cushing syndrome","Acute isolated insulin deficiency"],"answer":"C","whyCorrect":"Excess cortisol produces characteristic fat redistribution, skin changes, muscle catabolism and metabolic effects.","explanation":"Excess cortisol produces characteristic fat redistribution, skin changes, muscle catabolism and metabolic effects.","whyWrong":{"Chronic cortisol deficiency in Addison disease":"Cortisol deficiency more often causes weight loss and hypotension.","Thyroid hormone deficiency alone":"Hypothyroidism does not explain the classic glucocorticoid phenotype.","Acute isolated insulin deficiency":"Insulin deficiency alone does not produce this appearance."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-42","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":42,"topic":"Final Review Point 42","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 42","source":"Uploaded PCT II Final Review Sheet, Study Question 42","prompt":"Which comparison of viral hepatitis transmission routes is most accurate?","choices":["All five types spread primarily via inhaled respiratory droplets","Hepatitis A and E are predominantly fecal–oral; B and C are primarily blood/body-fluid related","Hepatitis A spreads chiefly through needle sharing, whereas B is fecal–oral","Hepatitis C is primarily acquired by contaminated drinking water"],"answer":"B","whyCorrect":"Hepatitis A/E usually spread by fecal–oral exposure; hepatitis B/C through blood and certain body fluids. Hepatitis D requires HBV coinfection.","explanation":"Hepatitis A/E usually spread by fecal–oral exposure; hepatitis B/C through blood and certain body fluids. Hepatitis D requires HBV coinfection.","whyWrong":{"All five types spread primarily via inhaled respiratory droplets":"Droplets are not the primary route of viral hepatitis.","Hepatitis A spreads chiefly through needle sharing, whereas B is fecal–oral":"This reverses key epidemiological routes.","Hepatitis C is primarily acquired by contaminated drinking water":"Hepatitis C is chiefly bloodborne rather than waterborne."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-43","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":43,"topic":"Final Review Point 43","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 43","source":"Uploaded PCT II Final Review Sheet, Study Question 43","prompt":"A worker splashes an unknown industrial chemical into the forearm, causing burning and damaged clothing. Which approach is safest in general?","choices":["Attempt chemical neutralization with a strong opposite-pH agent","Cover the chemical and wait until a definitive burn depth is clear","Protect rescuers, remove contaminated clothing and irrigate according to the substance-specific safety guidance","Apply ice directly to the contaminated area before decontamination"],"answer":"C","whyCorrect":"Chemical burns require immediate exposure termination, responder protection and appropriate decontamination; special agents can require specific exceptions.","explanation":"Chemical burns require immediate exposure termination, responder protection and appropriate decontamination; special agents can require specific exceptions.","whyWrong":{"Attempt chemical neutralization with a strong opposite-pH agent":"Neutralization can cause harmful exothermic reactions.","Cover the chemical and wait until a definitive burn depth is clear":"Waiting prolongs tissue exposure.","Apply ice directly to the contaminated area before decontamination":"Ice does not remove chemical contamination and can injure tissue."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-44","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":44,"topic":"Final Review Point 44","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 44","source":"Uploaded PCT II Final Review Sheet, Study Question 44","prompt":"A patient with blunt trauma to the left upper abdomen reports pain at the tip of the left shoulder. What is the basis of this referred pain?","choices":["Direct injury to the shoulder joint must be present","Isolated irritation of the sciatic nerve","Diaphragmatic irritation transmitted through the phrenic nerve","Spinal cord compression at a lumbar segment"],"answer":"C","whyCorrect":"Blood from splenic injury can irritate the diaphragm and refer pain to the shoulder via phrenic sensory pathways.","explanation":"Blood from splenic injury can irritate the diaphragm and refer pain to the shoulder via phrenic sensory pathways.","whyWrong":{"Direct injury to the shoulder joint must be present":"Referred pain does not require direct local shoulder damage.","Isolated irritation of the sciatic nerve":"Sciatic nerve covers lower-limb pathways.","Spinal cord compression at a lumbar segment":"Lumbar injury does not explain the classic Kehr sign."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-45","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":45,"topic":"Final Review Point 45","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 45","source":"Uploaded PCT II Final Review Sheet, Study Question 45","prompt":"After a chemical splash to the eye, which immediate priority best protects vision?","choices":["Patch both eyes tightly before removing the chemical","Begin copious appropriate eye irrigation without delaying for a complete eye examination","Attempt to scrape the corneal surface clean","Wait for pain to settle before decontamination"],"answer":"B","whyCorrect":"Prompt irrigation is crucial for many ocular chemical exposures; substance-specific precautions apply.","explanation":"Prompt irrigation is crucial for many ocular chemical exposures; substance-specific precautions apply.","whyWrong":{"Patch both eyes tightly before removing the chemical":"Patching traps chemical and delays removal.","Attempt to scrape the corneal surface clean":"Mechanical scraping can worsen injury.","Wait for pain to settle before decontamination":"Delay increases contact time and injury risk."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-46","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":46,"topic":"Final Review Point 46","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 46","source":"Uploaded PCT II Final Review Sheet, Study Question 46","prompt":"A patient has a dry, leathery, insensate central burn area surrounded by painful red tissue. Which central burn depth is most likely?","choices":["Full-thickness burn destroying the skin's sensory nerve endings","Superficial epidermal burn with intact dermis","Superficial partial-thickness burn characterized by intact painful blistering","An isolated first-degree burn without dermal damage"],"answer":"A","whyCorrect":"Full-thickness burns may be leathery and relatively insensate centrally because cutaneous nerves are destroyed.","explanation":"Full-thickness burns may be leathery and relatively insensate centrally because cutaneous nerves are destroyed.","whyWrong":{"Superficial epidermal burn with intact dermis":"Superficial burns are generally painful and erythematous.","Superficial partial-thickness burn characterized by intact painful blistering":"Superficial partial-thickness burns are often moist, blistered and very painful.","An isolated first-degree burn without dermal damage":"First-degree burns do not create leathery full-depth injury."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-47","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":47,"topic":"Final Review Point 47","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 47","source":"Uploaded PCT II Final Review Sheet, Study Question 47","prompt":"Why can a ruptured esophageal varix rapidly lead to profound shock even when there is no abdominal perforation?","choices":["A high-flow portosystemic collateral can bleed massively into the upper GI tract","Rupture necessarily causes only a small capillary ooze","It eliminates the ability to absorb oral glucose without causing blood loss","It releases pancreatic enzymes directly into the peritoneum"],"answer":"A","whyCorrect":"Dilated submucosal veins may rupture and cause massive upper GI hemorrhage with hypovolemic shock.","explanation":"Dilated submucosal veins may rupture and cause massive upper GI hemorrhage with hypovolemic shock.","whyWrong":{"Rupture necessarily causes only a small capillary ooze":"Varices can cause major rather than trivial hemorrhage.","It eliminates the ability to absorb oral glucose without causing blood loss":"Glucose absorption is not the primary acute mechanism.","It releases pancreatic enzymes directly into the peritoneum":"Pancreatic enzyme release describes a different pathology."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-48","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":48,"topic":"Final Review Point 48","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 48","source":"Uploaded PCT II Final Review Sheet, Study Question 48","prompt":"A patient suddenly develops unilateral facial droop, arm weakness and dysarthria. Which explanation best defines a CVA?","choices":["A temporary increase in stomach acidity affecting peripheral nerves","An acute neurological deficit due to interrupted brain blood flow or intracranial bleeding","A chronic primary muscle disorder without brain involvement","A predictable brief faint from standing with full and rapid recovery"],"answer":"B","whyCorrect":"Stroke (CVA) can be ischemic or hemorrhagic and causes focal neurological dysfunction.","explanation":"Stroke (CVA) can be ischemic or hemorrhagic and causes focal neurological dysfunction.","whyWrong":{"A temporary increase in stomach acidity affecting peripheral nerves":"GI acidity does not cause this focal cerebral syndrome.","A chronic primary muscle disorder without brain involvement":"Muscle disease does not explain an abrupt focal brain deficit.","A predictable brief faint from standing with full and rapid recovery":"Syncope differs from persistent focal deficits."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-49","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":49,"topic":"Final Review Point 49","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 49","source":"Uploaded PCT II Final Review Sheet, Study Question 49","prompt":"A patient with suspected overdose has marked respiratory depression, pinpoint pupils and reduced consciousness. Which drug class is most consistent?","choices":["Opioid toxicity","Sympathomimetic stimulant toxicity","Anticholinergic toxicity","Uncomplicated alcohol withdrawal"],"answer":"A","whyCorrect":"Opioid overdose classically causes respiratory depression, CNS depression and often miosis.","explanation":"Opioid overdose classically causes respiratory depression, CNS depression and often miosis.","whyWrong":{"Sympathomimetic stimulant toxicity":"Stimulants more often cause agitation, tachycardia and dilated pupils.","Anticholinergic toxicity":"Anticholinergics typically cause dryness, mydriasis and altered behavior.","Uncomplicated alcohol withdrawal":"Alcohol withdrawal usually causes autonomic excitation rather than opioid-pattern respiratory depression."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."},{"id":"PCT2-FINAL-REVIEW-1144-50","course":"Patient Care & Theory II","unit":"PCT II Instructor Final Review","bankType":"instructor-review","difficulty":"Instructor High","reviewPoint":50,"topic":"Final Review Point 50","sourceTitle":"PCT 2 Final Reveiw.docx","sourceLocator":"Study Question 50","source":"Uploaded PCT II Final Review Sheet, Study Question 50","prompt":"Two patients suffer gunshot wounds of similar external size. Which finding most strongly indicates the potential for greater internal damage?","choices":["The skin entry hole's appearance alone","Whether the patient's clothing has a large visible tear","The distance between the injury and the nearest ambulance","Projectile trajectory and energy transfer through vital structures"],"answer":"D","whyCorrect":"Internal injury depends on projectile energy, path, cavitation and vulnerable tissues crossed.","explanation":"Internal injury depends on projectile energy, path, cavitation and vulnerable tissues crossed.","whyWrong":{"The skin entry hole's appearance alone":"Entry wound size can poorly predict deep injury.","Whether the patient's clothing has a large visible tear":"Clothing damage does not reliably show internal trajectory.","The distance between the injury and the nearest ambulance":"Ambulance distance affects access to care, not underlying wound severity."},"scopeNote":"Education and review. Clinical directive application governed by current approved Ontario BLS/ALS PCS."}];})();